// Ellipsoidal Albers (WGS84), matching the build projection exactly.
function point(key,p){
 const d=DATA[key],c=d.projection,read=n=>Number(c.crs.match(new RegExp('\\+'+n+'=([-\\d.]+)'))[1]),rad=Math.PI/180,e=Math.sqrt(0.0066943799901413165),a=6378137;
 const q=t=>(1-e*e)*(Math.sin(t)/(1-e*e*Math.sin(t)**2)-Math.log((1-e*Math.sin(t))/(1+e*Math.sin(t)))/(2*e));
 const m=t=>Math.cos(t)/Math.sqrt(1-e*e*Math.sin(t)**2),p1=read('lat_1')*rad,p2=read('lat_2')*rad,n=(m(p1)**2-m(p2)**2)/(q(p2)-q(p1)),C=m(p1)**2+n*q(p1),rho=t=>a*Math.sqrt(C-n*q(t))/n,r0=rho(read('lat_0')*rad),r=rho(p[1]*rad),theta=n*(p[0]-read('lon_0'))*rad;
 return [(r*Math.sin(theta)-c.cx)*c.scale+d.w/2,(c.cy-r0+r*Math.cos(theta))*c.scale+d.h/2];
}
const line=(key,ps)=>ps.map((p,i)=>`${i?'L':'M'}${point(key,p).map(v=>v.toFixed(1)).join(',')}`).join('');
const label=(p,s,color='#17364a')=>`<circle cx="${p[0]}" cy="${p[1]}" r="12" fill="white" stroke="${color}" stroke-width="2"/><text x="${p[0]}" y="${p[1]+5}" text-anchor="middle" font-size="15" font-weight="800" fill="#17364a">${s}</text>`;
function base(key,overlay,caption){const d=DATA[key],file={na:'north-america',voyage:'atlantic',ga:'georgia'}[key];
 const oceans=key==='ga'?[[[-80.5,31.2],text('Atlantic','대서양')]]:key==='voyage'?[[[-105,10],text('Pacific','태평양')],[[-35,34],text('Atlantic','대서양')],[[-91,24],text('Gulf of Mexico','멕시코만')]]:[[[ -145,30],text('Pacific','태평양')],[[-58,29],text('Atlantic','대서양')],[[-91,24],text('Gulf of Mexico','멕시코만')]];
 // The north arrow follows the local meridian; Albers does not have north vertical everywhere.
 const arrowP=key==='ga'?[-80.4,34.4]:key==='voyage'?[-25,57]:[-60,60],ap=point(key,arrowP),an=point(key,[arrowP[0],arrowP[1]+2]),angle=Math.atan2(an[0]-ap[0],ap[1]-an[1])*180/Math.PI;
 return `<div class="real-map"><svg viewBox="0 0 ${d.w} ${d.h}" role="img" aria-label="${text('Geographic map with terrain relief','실제 지형 음영 지도')}"><image href="maps/${file}.webp" width="${d.w}" height="${d.h}"/><path d="${d.land}" fill="none" stroke="#566a56" stroke-width=".8"/><path d="${d.states}" fill="none" stroke="#596b77" stroke-width=".55" opacity=".6"/><path d="${d.lakes}" fill="#bddfe9" stroke="#728b96" stroke-width=".5"/>${overlay}${oceans.map(([p,s])=>{const xy=point(key,p);return `<text x="${xy[0]}" y="${xy[1]}" text-anchor="middle" font-size="14" fill="#164961" stroke="#eaf4f6" stroke-width="3" paint-order="stroke">${s}</text>`;}).join('')}<g transform="translate(${ap}) rotate(${angle})"><path d="M0 15V-15L-5 -5M0 -15L5 -5" stroke="#17364a" stroke-width="2" fill="none"/><text y="-20" text-anchor="middle" font-size="15" fill="#17364a">N</text></g></svg><div class="real-map-credit">${caption?caption+' · ':''}${text('Map data: Natural Earth','지도 자료: Natural Earth')}${key==='ga'?'; USGS; U.S. Census Bureau':''}</div></div>`;
}
const location=(rows,i,m)=>rows[0].n.en==='Arctic'?DATA.na.regionAnchors[i][m%2]:rows[i].p[m%rows[i].p.length];
function north(rows,a,m,b=-1){
 const type=rows[0].n.en==='Mississippi'?'rivers':rows[0].n.en==='Arctic'?'regions':rows[0].n.en==='Rocky Mountains'?'mountains':'voyages',key=type==='voyages'?'voyage':'na',d=DATA[key];
 const paths=type==='voyages'?rows.map(r=>line(key,r.p)):d[type];
 const selected=[a,b].filter(i=>i>=0);
 let overlay=paths.map((p,i)=>`<path d="${p}" fill="${type==='regions'?colors[i]:'none'}" fill-opacity="${selected.includes(i)?'.40':'.13'}" stroke="${selected.includes(i)?colors[i]:'#526e80'}" stroke-width="${type==='regions'?1:selected.includes(i)?4:1.2}" ${type==='voyages'?'stroke-dasharray="7 5"':''} stroke-linecap="round"/>`).join('');
 if(type==='voyages')overlay+=rows.map((r,i)=>[r.p[0],r.p[r.p.length-1]].map(p=>{const xy=point(key,p);return `<circle cx="${xy[0]}" cy="${xy[1]}" r="3" fill="${colors[i]}"/>`;}).join('')).join('');
 // Labels sit in empty space with leaders for lines; regions have labels inside their colored area.

 overlay+=selected.map((i,k)=>{const anchor=point(key,location(rows,i,m));const p=type==='regions'?anchor:[anchor[0]+(k?-20:20),anchor[1]-18];return (type==='regions'?'':`<path d="M${anchor}L${p}" stroke="#17364a" stroke-width="1"/>`)+label(p,k?'B':'A',colors[i]);}).join('');
 return base(key,overlay,type==='voyages'?text('Approximate routes','대략적인 경로'):type==='regions'?text('Broad regions, not borders','넓은 지역, 경계 아님'):'');
}
function georgia(o={}){const d=DATA.ga;
 let overlay='';
 if(o.region!==undefined)overlay+=d.regions.map((p,i)=>`<path d="${p}" fill="${colors[i]}" fill-opacity="${i===o.region?'.5':'.16'}" stroke="#4d4955" stroke-width="1.2"/>`).join('')+d.labels.map((p,i)=>label(p,i+1,colors[i])).join('');
 overlay+=`<path d="${d.outline}" fill="none" stroke="#17364a" stroke-width="2"/>`;
 if(o.region===undefined){overlay+=d.rivers.map((p,i)=>`<path d="${p}" fill="none" stroke="${o.river===['cha','sv','alt','fl'][i]?'#c42d50':'#156ba2'}" stroke-width="${o.river===['cha','sv','alt','fl'][i]?4:1.5}"/>`).join('');
 overlay+=d.cities.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="${o.city===['atl','sav','aug','col','mac'][i]?7:4}" fill="${o.city===['atl','sav','aug','col','mac'][i]?'#c42d50':'#17364a'}" stroke="white"/>${o.names?`<text x="${p[0]+(i===1||i===2?-9:8)}" y="${p[1]+(i===1?18:-7)}" text-anchor="${i===1||i===2?'end':'start'}" font-size="15" fill="#17364a" stroke="white" stroke-width="3" paint-order="stroke">${text(['Atlanta','Savannah','Augusta','Columbus','Macon'][i],['애틀랜타','서배너','오거스타','콜럼버스','메이컨'][i])}</text>`:''}`).join('');
 overlay+= [[-84.2,34.85],[-83.7,34.85],[-84.65,34.7]].map(p=>{const [x,y]=point('ga',p);return `<path d="M${x-5},${y+4}L${x},${y-5}L${x+5},${y+4}Z" fill="#70482f"/>`;}).join('');const [x,y]=point('ga',[-82.3,30.85]);overlay+=`<ellipse cx="${x}" cy="${y}" rx="13" ry="7" fill="#397f42"/>`;
 if(o.states)overlay+=[['TN',[-85,35.35]],['NC',[-82.7,35.35]],['SC',[-81.1,33.8]],['AL',[-86.4,32.5]],['FL',[-83.8,30.2]]].map(([s,p])=>{const xy=point('ga',p);return `<text x="${xy[0]}" y="${xy[1]}" font-size="16" fill="#17364a">${s}</text>`;}).join('');}
 return base('ga',overlay,'');
}
